<script setup lang="ts">
import { computed,reactive,watch,ref } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { api } from '../api/client';
import { useRemote } from '../composables/useRemote';
import { useSessionStore } from '../stores/session';
import { parseM4Filters,m4Query } from '../domain/m4';
import { formatFen,shanghaiTime } from '../domain/m1';
import { signedFen } from '../domain/m2';
import ErrorPanel from '../components/ErrorPanel.vue';
import PagePagination from '../components/PagePagination.vue';
import M4Navigation from '../components/M4Navigation.vue';
import M4ConfirmAction from '../components/M4ConfirmAction.vue';
import ReportFinancialSummary from '../components/ReportFinancialSummary.vue';
const route=useRoute(),router=useRouter(),session=useSessionStore();const filters=computed(()=>parseM4Filters(route.query,'report'));const form=reactive({storeId:'',from:'',to:''});const validation=ref(''),notice=ref('');
const overview=useRemote(()=>api.getReportOverview(filters.value));const orders=useRemote(()=>api.listReportOrders(filters.value));const stores=useRemote(()=>api.listStores(100,0));
function reload(){void overview.load();void orders.load();}
watch(()=>route.fullPath,()=>{Object.assign(form,{storeId:filters.value.storeId??'',from:filters.value.from??'',to:filters.value.to??''});reload();},{immediate:true});void stores.load();
function apply(){validation.value='';const dates=[form.from,form.to].filter(Boolean);if(dates.some(value=>!/^\d{4}-\d{2}-\d{2}T.*(?:Z|[+-]\d{2}:\d{2})$/.test(value)||!Number.isFinite(Date.parse(value)))||(form.from&&form.to&&Date.parse(form.from)>=Date.parse(form.to))){validation.value='请输入带 Z 或时区偏移的 ISO 时间，开始时间须早于结束时间。';return;}void router.push({path:'/reports',query:m4Query({...filters.value,...form,offset:0},'report')});}
function paginate(offset:number,limit:number){void router.push({path:'/reports',query:m4Query({...filters.value,offset,limit},'report')});}
async function refresh(key:string){await api.refreshReports(key);notice.value='报表投影刷新已排队，请稍后刷新查看 asOf 与待更新数量。';reload();}
</script>
<template><div><div class="page-heading"><div><p class="eyebrow">经营报表 / Mock</p><h1>经营报表</h1><p class="muted">预计利润、实际收付和退款分别记录 · Asia/Shanghai</p></div><el-button @click="reload">刷新报表</el-button></div><M4Navigation /><section class="panel filter-panel"><form data-testid="report-filters" class="filter-form" @submit.prevent="apply"><label>店铺<select v-model="form.storeId" name="storeId"><option value="">全部可见店铺</option><option v-for="store in stores.data.value?.items" :key="store.id" :value="store.id">{{ store.displayName }}</option></select></label><label>订单创建起始时间（ISO，含时区）<input v-model="form.from" name="from" placeholder="2026-10-01T00:00:00+08:00" /></label><label>订单创建结束时间（ISO，含时区）<input v-model="form.to" name="to" placeholder="2026-11-01T00:00:00+08:00" /></label><el-button native-type="submit" type="primary">查询</el-button><M4ConfirmAction v-if="session.can('reports.manage')" label="重建 Mock 报表投影" :context="route.fullPath" :run="refresh" /></form><p v-if="validation" class="field-error" role="alert">{{ validation }}</p><ErrorPanel v-if="stores.error.value" :error="stores.error.value" title="店铺范围读取失败"><el-button @click="stores.load">重试店铺</el-button></ErrorPanel><p class="help-text">留空使用服务端默认范围。统计口径是所选创建时间内各订单最新投影的累计收付，不是期间收付流水；asOf 表示最早投影核验时间。</p></section><p v-if="notice" class="success-note">{{ notice }}</p><div v-if="overview.loading.value" class="panel data-state" role="status"><el-skeleton :rows="6" animated /></div><ErrorPanel v-else-if="overview.error.value" :error="overview.error.value" title="经营汇总读取失败"><el-button @click="overview.load">重试汇总</el-button></ErrorPanel><ReportFinancialSummary v-else-if="overview.data.value" :report="overview.data.value" /><section class="panel table-panel"><h2 class="section-title">订单经营明细</h2><p v-if="orders.loading.value" class="data-state" role="status">正在读取明细…</p><ErrorPanel v-else-if="orders.error.value" :error="orders.error.value" title="经营明细读取失败"><el-button @click="orders.load">重试明细</el-button></ErrorPanel><div v-else-if="!orders.data.value?.items.length" class="data-state">暂无匹配订单明细</div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>销售订单 / 创建时间</th><th>销售实收 / 采购实付</th><th>预计成本 / 预计利润</th><th>销售退款 / 供应商退款</th><th>净现金流 / 实际净利润</th><th>未对账 / 待供应商退款</th></tr></thead><tbody><tr v-for="item in orders.data.value.items" :key="item.salesOrderId"><td><RouterLink class="text-link" :to="`/orders/${item.salesOrderId}`">{{ item.externalOrderId }}</RouterLink><small>{{ shanghaiTime(item.createdAt) }}</small></td><td>{{ formatFen(item.salesPaidFen) }}<small>{{ formatFen(item.purchasePaidFen) }}</small></td><td>{{ formatFen(item.estimatedPurchaseFen) }}<small>{{ signedFen(item.estimatedProfitFen) }}</small></td><td>{{ formatFen(item.salesRefundedFen) }}<small>{{ formatFen(item.supplierRefundedFen) }}</small></td><td>{{ signedFen(item.netCashFlowFen) }}<small>实际净利润：成本不完整</small></td><td>{{ item.unreconciledCount }} / {{ formatFen(item.unreconciledPaymentFen) }}<small>{{ formatFen(item.pendingSupplierRefundFen) }}</small></td></tr></tbody></table></div><PagePagination v-if="orders.data.value" :total="orders.data.value.total" :limit="filters.limit" :offset="filters.offset" :loading="orders.loading.value" @change="paginate" /></section></div></template>
